import { claimsQueryKey } from '../claims/claims';
import { peoplePath, peopleQueryKey, type Person } from '../people/people';

// A person's statements: how many were taken, the last one's due-total and date, and the button that takes
// one — recording their due-total now and binding each of their counted claims to the figure it has now; or, with a
// date in the entry beside it (on or before the sheet's today), as of the end of that date — and the
// button a steward cancels the last one with, making the claims it bound live again (anyone else, or a person with no
// statement, shows the row's error).
function StatementHeader() {
  return <th>Statements</th>;
}

function PersonStatement({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const today = useSheetToday();
  const [asOf, setAsOf] = useState('');
  const queryClient = useQueryClient();
  const take = useMutation({
    mutationFn: (date: string) =>
      putJson<Person>(`${peoplePath(sheet ?? '')}/${person.id}/statement`
        + (date.trim() ? `?asOf=${encodeURIComponent(date.trim())}` : ''), undefined, user),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet ?? '') }),
        queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet ?? '') }),
      ]);
    },
    // A date typed for one statement, taken or refused, never carries into the next.
    onSettled: () => setAsOf(''),
  });
  const submit = useSubmitOnce(take);
  const rowAction = useRowAction(`person-${person.id}`);
  const cancel = useMutation({
    mutationFn: () => putJson<Person>(`${peoplePath(sheet ?? '')}/${person.id}/unstate`, undefined, user),
    onSuccess: () =>
      Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet ?? '') }),
        queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet ?? '') }),
      ]),
  });
  const submitCancel = useSubmitOnce(cancel);
  const cancelAction = useRowAction(`person-${person.id}`);
  return (
    <td>
      <span data-testid="person-statement-count">{person.statementCount}</span>{' '}
      <span data-testid="person-stated-total">{person.statedTotal ?? ''}</span>{' '}
      <span data-testid="person-statement-date">{person.statementDate ?? ''}</span>{' '}
      <input
        data-testid="person-statement-asof"
        placeholder={today ?? 'as of'}
        value={asOf}
        onChange={(e) => { setAsOf(e.target.value); take.reset(); }}
    mutationFn: (body: { patronId: number }) =>
      postJson<Person>(`${peoplePath(sheet ?? '')}/${person.id}/patrons`, body, user),
    onSuccess: () => {
      setChosen('');
      return queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet ?? '') });
    },
  });
  const submit = useSubmitOnce(add);
  const rowAction = useRowAction(`person-${person.id}`);
  const everyone = people.data ?? [];
  const patrons = person.patronIds
    .map((id) => everyone.find((p) => p.id === id))
    .filter((p): p is Person => p !== undefined);
  const shares = sharesOf(patrons.length);
  const names = patrons.map((p, i) => ({ name: p.name, share: formatCents(shares[i]) }))
    .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
    .map((p) => `${p.name} ${p.share}`);
  const backing = backingOf(patrons, claims.data ?? [], today);
  return (
    <>
      <td>
        <span data-testid="person-patrons">{names.join(', ')}</span>{' '}
        <select
          data-testid="person-patron-select"
          value={chosen}
          onChange={(e) => {
            setChosen(e.target.value);
            add.reset();
          }}
        >
          <option value="">Choose a patron</option>
          {everyone.filter((p) => p.id !== person.id).map((p) => (
            <option key={p.id} value={String(p.id)}>{p.name}</option>
          ))}
        </select>
        <button
          type="button"
          data-testid="person-patron-add"
          disabled={add.isPending}
          onClick={() => { rowAction.take(); submit({ patronId: Number(chosen) }); }}
        >
          Add patron
        </button>
        {add.isError && rowAction.isLatest && <span data-testid="person-patron-error">The patron could not be added.</span>}
      </td>
      <td data-testid="person-backing">{backing}</td>
    </>
  );
}

